import Link from "next/link";
import { ArrowLeft } from "lucide-react";
import { SITE, formatDate, readingTime } from "@/lib/site";
import { SanitizedContent } from "@/components/SanitizedContent";
import { CommentsSection } from "@/components/blog/CommentsSection";

type PostWithRelations = {
  title: string;
  slug: string;
  excerpt: string | null;
  content: string;
  coverImage: string | null;
  kicker: string | null;
  showCover: boolean;
  footerNote: string | null;
  showAuthorBox: boolean;
  publishedAt: Date;
  category?: { name: string } | null;
  author?: { name: string | null } | null;
};

export function PostArticle({ post }: { post: PostWithRelations }) {
  return (
    <article className="mx-auto max-w-3xl px-4 sm:px-6 py-16">
      <Link
        href="/blog"
        className="inline-flex items-center gap-1.5 text-sm font-medium text-muted-foreground hover:text-foreground transition-colors"
      >
        <ArrowLeft className="w-4 h-4" /> All articles
      </Link>

      <header className="mt-8">
        {post.kicker && (
          <p className="text-xs font-semibold uppercase tracking-widest text-muted-foreground">
            {post.kicker}
          </p>
        )}
        {post.category && (
          <span className="mt-2 inline-block text-xs font-semibold uppercase tracking-wider text-accent-strong">
            {post.category.name}
          </span>
        )}
        <h1 className="mt-3 font-display text-3xl sm:text-4xl md:text-5xl font-bold leading-tight">
          {post.title}
        </h1>
        {post.excerpt && (
          <p className="mt-5 text-lg text-muted-foreground leading-relaxed">
            {post.excerpt}
          </p>
        )}
        <div className="mt-6 flex flex-wrap items-center gap-2 text-sm text-muted-foreground">
          <span className="font-medium text-foreground">
            {post.author?.name ?? "Sagar Lad"}
          </span>
          <span aria-hidden="true">·</span>
          <time dateTime={post.publishedAt.toISOString()}>
            {formatDate(post.publishedAt)}
          </time>
          <span aria-hidden="true">·</span>
          <span>{readingTime(post.content)} min read</span>
        </div>
      </header>

      <div className="my-8 h-px bg-border" />

      <div id="post-content">
        {post.coverImage && post.showCover && (
          <div className="mb-8 overflow-hidden rounded-3xl border border-border">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              src={post.coverImage}
              alt=""
              className="w-full aspect-[16/9] object-cover"
            />
          </div>
        )}

        <SanitizedContent html={post.content} />
      </div>

      {post.footerNote && (
        <div className="mt-10 rounded-2xl border border-border bg-muted/40 p-5 text-sm text-muted-foreground">
          {post.footerNote}
        </div>
      )}

      {post.showAuthorBox && (
        <div className="mt-6 flex items-center gap-4 rounded-2xl border border-border bg-card p-6">
          <div className="grid h-12 w-12 shrink-0 place-items-center rounded-full bg-accent font-display text-lg font-bold text-accent-foreground">
            {(post.author?.name ?? SITE.name).charAt(0)}
          </div>
          <div>
            <p className="font-display font-bold">{post.author?.name ?? SITE.name}</p>
            <p className="mt-0.5 text-sm text-muted-foreground">
              {SITE.description}
            </p>
          </div>
        </div>
      )}

      <CommentsSection postSlug={post.slug} />
    </article>
  );
}
